from collections import Counter
from copy import deepcopy

def flood_fill(grid, start_i, start_j, target_val, visited=None):
    """Count cells of given value reachable from start"""
    if visited is None:
        visited = set()
    if (start_i, start_j) in visited:
        return 0
    visited.add((start_i, start_j))
    count = 1
    H, W = len(grid), len(grid[0])
    for di in [-1, 0, 1]:
        for dj in [-1, 0, 1]:
            ni, nj = start_i + di, start_j + dj
            if 0 <= ni < H and 0 <= nj < W:
                if grid[ni][nj] == target_val and (ni, nj) not in visited:
                    count += flood_fill(grid, ni, nj, target_val, visited)
    return count

def transform_by_region_size(grid):
    result = [[c for c in row] for row in grid]
    H, W = len(grid), len(grid[0])
    for i in range(H):
        for j in range(W):
            if grid[i][j] in [0, 4, 8]:
                # Count 8-way connected region sizes for each neighbor color
                region_counts = Counter()
                for di in [-1, 0, 1]:
                    for dj in [-1, 0, 1]:
                        if di == 0 and dj == 0:
                            continue
                        ni, nj = i + di, j + dj
                        if 0 <= ni < H and 0 <= nj < W:
                            color = grid[ni][nj]
                            region_counts[color] = flood_fill(grid, i, j, color)

                print(f"  Region sizes for ({i},{j}): {dict(region_counts)}")

                if region_counts:
                    result[i][j] = region_counts.most_common(1)[0][0]
                else:
                    result[i][j] = grid[i][j]
    return result

