def get_8way_region_count(grid, i, j, target_color):
    """Count cells of given color reachable with 8-way connectivity"""
    visited = set()
    queue = [(i, j)]
    while queue:
        (ci, cj) = queue.pop(0)
        if (ci, cj) in visited:
            continue
        visited.add((ci, cj))
        color = grid[ci][cj]
        if color != target_color:
            continue
        for di in [-1, 0, 1]:
            for dj in [-1, 0, 1]:
                ni, nj = ci + di, cj + dj
                if 0 <= ni < len(grid) and 0 <= nj < len(grid[0]):
                    if (ni, nj) not in visited and grid[ni][nj] == target_color:
                        queue.append((ni, nj))
    return len(visited)

def transform_by_region_size(grid):
    result = [[c for c in row] for row in grid]
    H, W = len(grid), len(grid[0])
    for i in range(H):
        for j in range(W):
            if grid[i][j] in [0, 4, 8]:
                region_counts = Counter()
                for di in [-1, 0, 1]:
                    for dj in [-1, 0, 1]:
